handlers.onSelect:
{() => {
                const id = store.duplicateWorkflow(workflow.id);
                if (id) navigate({ to: "/app/workflows/$id", params: { id } });
              }}

handlers.onNodeDragStop:
{() => {
                  if (dragStart.current) { const previous = dragStart.current; setPast(p=>[...p.slice(-49),previous]); setFuture([]); dragStart.current=null; }
                  commit({ nodes: nodesRef.current, edges: edgesRef.current }, {history:false});
                }}

handlers.onSubmit:
{(e) => {
          e.preventDefault();
          if (source && target && (!outcomes.length || label))
            onConnect(source, target, label || undefined);
        }}

handlers.onPointerDown:
{event => {
          if(event.button !== 0) return;
          drag.current = {x: event.clientX, y: event.clientY, left: camera.x, top: camera.y};
          event.currentTarget.setPointerCapture(event.pointerId);
        }}

handlers.onPointerMove:
{event => {
          const start = drag.current;
          const matrix = svg.current?.getScreenCTM();
          if(!start || !matrix) return;
          setCamera(value => ({...value, x: start.left - (event.clientX - start.x) / matrix.a, y: start.top - (event.clientY - start.y) / matrix.d}));
        }}

handlers.onCreated:
{({ gl }) => {
        gl.toneMapping = THREE.ACESFilmicToneMapping;
        gl.toneMappingExposure = 0.95;
        gl.domElement.addEventListener("webglcontextlost", (e) => {
          e.preventDefault();
          onContextLost();
        });
      }}

handlers.onClick:
{() =>
              useMesh.setState((s) => ({
                workflows: s.workflows.map((w) =>
                  w.id === workflow.id ? { ...w, tabConflict: undefined } : w,
                ),
              }))
            }

{() => {
            try {
              const state = useMesh.getState();
              setExported(
                JSON.stringify(
                  {
                    format: "mesh-working-draft-recovery-v1",
                    workflow,
                    agents: state.agents.filter((a) => ownsAgent(workflow, a)),
                  },
                  null,
                  2,
                ),
              );
            } catch (caught) {
              setError(caught instanceof Error ? caught : new Error("Export unavailable."));
            }
          }}
